    Av1Settings.add_member(:afd_signaling, Smithy::Schema::Shapes::ShapeRef.new(shape: AfdSignaling, location_name: 'AfdSignaling', traits: {"smithy.api#documentation" => "Configures whether MediaLive will write AFD values into the video.\nAUTO: MediaLive will try to preserve the input AFD value (in cases where multiple AFD values are valid).\nFIXED: the AFD value will be the value configured in the fixedAfd parameter.\nNONE: MediaLive won't write AFD into the video", "smithy.api#jsonName" => "afdSignaling"}))
    Av1Settings.add_member(:buf_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin50000max16000000, location_name: 'BufSize', traits: {"smithy.api#documentation" => "The size of the buffer (HRD buffer model) in bits.", "smithy.api#jsonName" => "bufSize"}))
    Av1Settings.add_member(:color_space_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1ColorSpaceSettings, location_name: 'ColorSpaceSettings', traits: {"smithy.api#documentation" => "Color Space settings", "smithy.api#jsonName" => "colorSpaceSettings"}))
    Av1Settings.add_member(:fixed_afd, Smithy::Schema::Shapes::ShapeRef.new(shape: FixedAfd, location_name: 'FixedAfd', traits: {"smithy.api#documentation" => "Complete this property only if you set the afdSignaling property to FIXED. Choose the AFD value (4 bits) to write on all frames of the video encode.", "smithy.api#jsonName" => "fixedAfd"}))
    Av1Settings.add_member(:framerate_denominator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max3003, location_name: 'FramerateDenominator', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "The denominator for the framerate. Framerate is a fraction, for example, 24000 / 1001.", "smithy.api#jsonName" => "framerateDenominator", "smithy.api#required" => {}}))
    Av1Settings.add_member(:framerate_numerator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'FramerateNumerator', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "The numerator for the framerate. Framerate is a fraction, for example, 24000 / 1001.", "smithy.api#jsonName" => "framerateNumerator", "smithy.api#required" => {}}))
    Av1Settings.add_member(:gop_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Doublemin0, location_name: 'GopSize', traits: {"smithy.api#documentation" => "The GOP size (keyframe interval).\nIf GopSizeUnits is frames, GopSize must be a whole number and must be greater than or equal to 1.\nIf GopSizeUnits is seconds, GopSize must be greater than 0, but it can be a decimal.", "smithy.api#jsonName" => "gopSize"}))
    Av1Settings.add_member(:gop_size_units, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1GopSizeUnits, location_name: 'GopSizeUnits', traits: {"smithy.api#documentation" => "Choose the units for the GOP size: FRAMES or SECONDS. For SECONDS, MediaLive converts the size into a frame count at run time.", "smithy.api#jsonName" => "gopSizeUnits"}))
    Av1Settings.add_member(:level, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1Level, location_name: 'Level', traits: {"smithy.api#documentation" => "Sets the level. This parameter is one of the properties of the encoding scheme for AV1.", "smithy.api#jsonName" => "level"}))
    Av1Settings.add_member(:look_ahead_rate_control, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1LookAheadRateControl, location_name: 'LookAheadRateControl', traits: {"smithy.api#documentation" => "Sets the amount of lookahead. A value of LOW can decrease latency and memory usage. A value of HIGH can produce better quality for certain content.", "smithy.api#jsonName" => "lookAheadRateControl"}))
    Av1Settings.add_member(:max_bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin50000max8000000, location_name: 'MaxBitrate', traits: {"smithy.api#documentation" => "The maximum bitrate to assign.\nFor recommendations, see the description for qvbrQualityLevel.", "smithy.api#jsonName" => "maxBitrate"}))
    Av1Settings.add_member(:min_i_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max30, location_name: 'MinIInterval', traits: {"smithy.api#documentation" => "Applies only if you enable SceneChangeDetect. Sets the interval between frames. This property ensures a minimum separation between repeated (cadence) I-frames and any I-frames inserted by scene change detection (SCD frames).\nEnter a number for the interval, measured in number of frames.\nIf an SCD frame and a cadence frame are closer than the specified number of frames, MediaLive shrinks or stretches the GOP to include the SCD frame. Then normal cadence resumes in the next GOP. For GOP stretch to succeed, you must enable LookAheadRateControl.\nNote that the maximum GOP stretch = (GOP size) + (Minimum I-interval) - 1", "smithy.api#jsonName" => "minIInterval"}))
    Av1Settings.add_member(:par_denominator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'ParDenominator', traits: {"smithy.api#documentation" => "The denominator for the output pixel aspect ratio (PAR).", "smithy.api#jsonName" => "parDenominator"}))
    Av1Settings.add_member(:par_numerator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'ParNumerator', traits: {"smithy.api#documentation" => "The numerator for the output pixel aspect ratio (PAR).", "smithy.api#jsonName" => "parNumerator"}))
    Av1Settings.add_member(:qvbr_quality_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max10, location_name: 'QvbrQualityLevel', traits: {"smithy.api#documentation" => "Controls the target quality for the video encode. With QVBR rate control mode, the final quality is the target quality, constrained by the maxBitrate.\nSet values for the qvbrQualityLevel property and maxBitrate property that suit your most important viewing devices.\nTo let MediaLive set the quality level (AUTO mode), leave the qvbrQualityLevel field empty. In this case, MediaLive uses the maximum bitrate, and the quality follows from that: more complex content might have a lower quality.\nOr set a target quality level and a maximum bitrate. With more complex content, MediaLive will try to achieve the target quality, but it won't exceed the maximum bitrate. With less complex content, This option will use only the bitrate needed to reach the target quality.\nRecommended values are:\nPrimary screen: qvbrQualityLevel: Leave empty. maxBitrate: 4,000,000\nPC or tablet: qvbrQualityLevel: Leave empty. maxBitrate: 1,500,000 to 3,000,000\nSmartphone: qvbrQualityLevel: Leave empty. maxBitrate: 1,000,000 to 1,500,000", "smithy.api#jsonName" => "qvbrQualityLevel"}))
    Av1Settings.add_member(:scene_change_detect, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1SceneChangeDetect, location_name: 'SceneChangeDetect', traits: {"smithy.api#documentation" => "Controls whether MediaLive inserts I-frames when it detects a scene change. ENABLED or DISABLED.", "smithy.api#jsonName" => "sceneChangeDetect"}))
    Av1Settings.add_member(:timecode_burnin_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: TimecodeBurninSettings, location_name: 'TimecodeBurninSettings', traits: {"smithy.api#documentation" => "Configures the timecode burn-in feature. If you enable this feature, the timecode will become part of the video.", "smithy.api#jsonName" => "timecodeBurninSettings"}))
    Av1Settings.add_member(:bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin50000max8000000, location_name: 'Bitrate', traits: {"smithy.api#documentation" => "Average bitrate in bits/second. Required when the rate control mode is CBR. Not used for QVBR.", "smithy.api#jsonName" => "bitrate"}))
    Av1Settings.add_member(:rate_control_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: Av1RateControlMode, location_name: 'RateControlMode', traits: {"smithy.api#documentation" => "Rate control mode.\n\nQVBR: Quality will match the specified quality level except when it is constrained by the\nmaximum bitrate.  Recommended if you or your viewers pay for bandwidth.\n\nCBR: Quality varies, depending on the video complexity. Recommended only if you distribute\nyour assets to devices that cannot handle variable bitrates.", "smithy.api#jsonName" => "rateControlMode"}))
    Av1Settings.type = Types::Av1Settings
    AvailBlanking.add_member(:avail_blanking_image, Smithy::Schema::Shapes::ShapeRef.new(shape: InputLocation, location_name: 'AvailBlankingImage', traits: {"smithy.api#documentation" => "Blanking image to be used. Leave empty for solid black. Only bmp and png images are supported.", "smithy.api#jsonName" => "availBlankingImage"}))
    AvailBlanking.add_member(:state, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailBlankingState, location_name: 'State', traits: {"smithy.api#documentation" => "When set to enabled, causes video, audio and captions to be blanked when insertion metadata is added.", "smithy.api#jsonName" => "state"}))
    AvailBlanking.type = Types::AvailBlanking
    AvailBlankingState.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    AvailBlankingState.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    AvailConfiguration.add_member(:avail_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailSettings, location_name: 'AvailSettings', traits: {"smithy.api#documentation" => "Controls how SCTE-35 messages create cues. Splice Insert mode treats all segmentation signals traditionally. With Time Signal APOS mode only Time Signal Placement Opportunity and Break messages create segment breaks. With ESAM mode, signals are forwarded to an ESAM server for possible update.", "smithy.api#jsonName" => "availSettings"}))
    AvailConfiguration.add_member(:scte35_segmentation_scope, Smithy::Schema::Shapes::ShapeRef.new(shape: Scte35SegmentationScope, location_name: 'Scte35SegmentationScope', traits: {"smithy.api#documentation" => "Configures whether SCTE 35 passthrough triggers segment breaks in all output groups that use segmented outputs. Insertion of a SCTE 35 message typically results in a segment break, in addition to the regular cadence of breaks. The segment breaks appear in video outputs, audio outputs, and captions outputs (if any).\n\nALL_OUTPUT_GROUPS: Default. Insert the segment break in in all output groups that have segmented outputs. This is the legacy behavior.\nSCTE35_ENABLED_OUTPUT_GROUPS: Insert the segment break only in output groups that have SCTE 35 passthrough enabled. This is the recommended value, because it reduces unnecessary segment breaks.", "smithy.api#jsonName" => "scte35SegmentationScope"}))
    AvailConfiguration.type = Types::AvailConfiguration
    AvailSettings.add_member(:esam, Smithy::Schema::Shapes::ShapeRef.new(shape: Esam, location_name: 'Esam', traits: {"smithy.api#jsonName" => "esam"}))
    AvailSettings.add_member(:scte35_splice_insert, Smithy::Schema::Shapes::ShapeRef.new(shape: Scte35SpliceInsert, location_name: 'Scte35SpliceInsert', traits: {"smithy.api#jsonName" => "scte35SpliceInsert"}))
    AvailSettings.add_member(:scte35_time_signal_apos, Smithy::Schema::Shapes::ShapeRef.new(shape: Scte35TimeSignalApos, location_name: 'Scte35TimeSignalApos', traits: {"smithy.api#jsonName" => "scte35TimeSignalApos"}))
    AvailSettings.type = Types::AvailSettings
