    BandwidthReductionFilterSettings.add_member(:post_filter_sharpening, Smithy::Schema::Shapes::ShapeRef.new(shape: BandwidthReductionPostFilterSharpening, location_name: 'PostFilterSharpening', traits: {"smithy.api#documentation" => "Configures the sharpening control, which is available when the bandwidth reduction filter is enabled. This\ncontrol sharpens edges and contours, which produces a specific artistic effect that you might want.\n\nWe recommend that you test each of the values (including DISABLED) to observe the sharpening effect on the\ncontent.", "smithy.api#jsonName" => "postFilterSharpening"}))
    BandwidthReductionFilterSettings.add_member(:strength, Smithy::Schema::Shapes::ShapeRef.new(shape: BandwidthReductionFilterStrength, location_name: 'Strength', traits: {"smithy.api#documentation" => "Enables the bandwidth reduction filter. The filter strengths range from 1 to 4. We recommend that you always\nenable this filter and use AUTO, to let MediaLive apply the optimum filtering for the context.", "smithy.api#jsonName" => "strength"}))
