    BandwidthReductionFilterStrength.add_member(:strength_2, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'STRENGTH_2', traits: {"smithy.api#enumValue" => "STRENGTH_2"}))
