    BlackoutSlate.add_member(:network_end_blackout, Smithy::Schema::Shapes::ShapeRef.new(shape: BlackoutSlateNetworkEndBlackout, location_name: 'NetworkEndBlackout', traits: {"smithy.api#documentation" => "Setting to enabled causes the encoder to blackout the video, audio, and captions, and raise the \"Network Blackout Image\" slate when an SCTE104/35 Network End Segmentation Descriptor is encountered. The blackout will be lifted when the Network Start Segmentation Descriptor is encountered. The Network End and Network Start descriptors must contain a network ID that matches the value entered in \"Network ID\".", "smithy.api#jsonName" => "networkEndBlackout"}))
