    BurnInDestinationSettings.add_member(:font, Smithy::Schema::Shapes::ShapeRef.new(shape: InputLocation, location_name: 'Font', traits: {"smithy.api#documentation" => "External font file used for caption burn-in. File extension must be 'ttf' or 'tte'.  Although the user can select output fonts for many different types of input captions,  embedded, STL and teletext sources use a strict grid system. Using external fonts with these caption sources could cause unexpected display of proportional fonts.  All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "font"}))
    BurnInDestinationSettings.add_member(:font_color, Smithy::Schema::Shapes::ShapeRef.new(shape: BurnInFontColor, location_name: 'FontColor', traits: {"smithy.api#documentation" => "Specifies the color of the burned-in captions.  This option is not valid for source captions that are STL, 608/embedded or teletext.  These source settings are already pre-defined by the caption stream.  All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "fontColor"}))
    BurnInDestinationSettings.add_member(:font_opacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max255, location_name: 'FontOpacity', traits: {"smithy.api#documentation" => "Specifies the opacity of the burned-in captions. 255 is opaque; 0 is transparent.  All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "fontOpacity"}))
    BurnInDestinationSettings.add_member(:font_resolution, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin96max600, location_name: 'FontResolution', traits: {"smithy.api#documentation" => "Font resolution in DPI (dots per inch); default is 96 dpi.  All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "fontResolution"}))
    BurnInDestinationSettings.add_member(:font_size, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'FontSize', traits: {"smithy.api#documentation" => "When set to 'auto' fontSize will scale depending on the size of the output.  Giving a positive integer will specify the exact font size in points.  All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "fontSize"}))
