    BurnInDestinationSettings.add_member(:outline_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max10, location_name: 'OutlineSize', traits: {"smithy.api#documentation" => "Specifies font outline size in pixels. This option is not valid for source captions that are either 608/embedded or teletext. These source settings are already pre-defined by the caption stream. All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "outlineSize"}))
