    BurnInDestinationSettings.add_member(:shadow_x_offset, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'ShadowXOffset', traits: {"smithy.api#documentation" => "Specifies the horizontal offset of the shadow relative to the captions in pixels. A value of -2 would result in a shadow offset 2 pixels to the left.  All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "shadowXOffset"}))
