    BurnInDestinationSettings.add_member(:teletext_grid_control, Smithy::Schema::Shapes::ShapeRef.new(shape: BurnInTeletextGridControl, location_name: 'TeletextGridControl', traits: {"smithy.api#documentation" => "Controls whether a fixed grid size will be used to generate the output subtitles bitmap. Only applicable for Teletext inputs and DVB-Sub/Burn-in outputs.", "smithy.api#jsonName" => "teletextGridControl"}))
