    DvbSubDestinationSettings.add_member(:alignment, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubDestinationAlignment, location_name: 'Alignment', traits: {"smithy.api#documentation" => "If no explicit xPosition or yPosition is provided, setting alignment to centered will place the captions at the bottom center of the output. Similarly, setting a left alignment will align captions to the bottom left of the output. If x and y positions are given in conjunction with the alignment parameter, the font will be justified (either left or centered) relative to those coordinates. Selecting \"smart\" justification will left-justify live subtitles and center-justify pre-recorded subtitles.  This option is not valid for source captions that are STL or 608/embedded.  These source settings are already pre-defined by the caption stream.  All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "alignment"}))
    DvbSubDestinationSettings.add_member(:background_color, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubDestinationBackgroundColor, location_name: 'BackgroundColor', traits: {"smithy.api#documentation" => "Specifies the color of the rectangle behind the captions.  All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "backgroundColor"}))
    DvbSubDestinationSettings.add_member(:background_opacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max255, location_name: 'BackgroundOpacity', traits: {"smithy.api#documentation" => "Specifies the opacity of the background rectangle. 255 is opaque; 0 is transparent. Leaving this parameter blank is equivalent to setting it to 0 (transparent).  All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "backgroundOpacity"}))
    DvbSubDestinationSettings.add_member(:font, Smithy::Schema::Shapes::ShapeRef.new(shape: InputLocation, location_name: 'Font', traits: {"smithy.api#documentation" => "External font file used for caption burn-in. File extension must be 'ttf' or 'tte'.  Although the user can select output fonts for many different types of input captions, embedded, STL and teletext sources use a strict grid system. Using external fonts with these caption sources could cause unexpected display of proportional fonts.  All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "font"}))
    DvbSubDestinationSettings.add_member(:font_color, Smithy::Schema::Shapes::ShapeRef.new(shape: DvbSubDestinationFontColor, location_name: 'FontColor', traits: {"smithy.api#documentation" => "Specifies the color of the burned-in captions.  This option is not valid for source captions that are STL, 608/embedded or teletext.  These source settings are already pre-defined by the caption stream.  All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "fontColor"}))
    DvbSubDestinationSettings.add_member(:font_opacity, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max255, location_name: 'FontOpacity', traits: {"smithy.api#documentation" => "Specifies the opacity of the burned-in captions. 255 is opaque; 0 is transparent.  All burn-in and DVB-Sub font settings must match.", "smithy.api#jsonName" => "fontOpacity"}))
