    H264Level.add_member(:h264_level_5, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'H264_LEVEL_5', traits: {"smithy.api#enumValue" => "H264_LEVEL_5"}))
    H264Level.add_member(:h264_level_5_1, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'H264_LEVEL_5_1', traits: {"smithy.api#enumValue" => "H264_LEVEL_5_1"}))
    H264Level.add_member(:h264_level_5_2, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'H264_LEVEL_5_2', traits: {"smithy.api#enumValue" => "H264_LEVEL_5_2"}))
    H264Level.add_member(:h264_level_auto, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'H264_LEVEL_AUTO', traits: {"smithy.api#enumValue" => "H264_LEVEL_AUTO"}))
    H264LookAheadRateControl.add_member(:high, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HIGH', traits: {"smithy.api#enumValue" => "HIGH"}))
    H264LookAheadRateControl.add_member(:low, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'LOW', traits: {"smithy.api#enumValue" => "LOW"}))
    H264LookAheadRateControl.add_member(:medium, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MEDIUM', traits: {"smithy.api#enumValue" => "MEDIUM"}))
    H264ParControl.add_member(:initialize_from_source, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INITIALIZE_FROM_SOURCE', traits: {"smithy.api#enumValue" => "INITIALIZE_FROM_SOURCE"}))
    H264ParControl.add_member(:specified, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'SPECIFIED', traits: {"smithy.api#enumValue" => "SPECIFIED"}))
    H264Profile.add_member(:baseline, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'BASELINE', traits: {"smithy.api#enumValue" => "BASELINE"}))
    H264Profile.add_member(:high, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HIGH', traits: {"smithy.api#enumValue" => "HIGH"}))
    H264Profile.add_member(:high_10_bit, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HIGH_10BIT', traits: {"smithy.api#enumValue" => "HIGH_10BIT"}))
    H264Profile.add_member(:high_422, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HIGH_422', traits: {"smithy.api#enumValue" => "HIGH_422"}))
    H264Profile.add_member(:high_422_10_bit, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'HIGH_422_10BIT', traits: {"smithy.api#enumValue" => "HIGH_422_10BIT"}))
    H264Profile.add_member(:main, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MAIN', traits: {"smithy.api#enumValue" => "MAIN"}))
    H264QualityLevel.add_member(:enhanced_quality, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENHANCED_QUALITY', traits: {"smithy.api#enumValue" => "ENHANCED_QUALITY"}))
    H264QualityLevel.add_member(:standard_quality, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'STANDARD_QUALITY', traits: {"smithy.api#enumValue" => "STANDARD_QUALITY"}))
    H264RateControlMode.add_member(:cbr, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'CBR', traits: {"smithy.api#enumValue" => "CBR"}))
    H264RateControlMode.add_member(:multiplex, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MULTIPLEX', traits: {"smithy.api#enumValue" => "MULTIPLEX"}))
    H264RateControlMode.add_member(:qvbr, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'QVBR', traits: {"smithy.api#enumValue" => "QVBR"}))
    H264RateControlMode.add_member(:vbr, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'VBR', traits: {"smithy.api#enumValue" => "VBR"}))
    H264ScanType.add_member(:interlaced, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'INTERLACED', traits: {"smithy.api#enumValue" => "INTERLACED"}))
    H264ScanType.add_member(:progressive, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'PROGRESSIVE', traits: {"smithy.api#enumValue" => "PROGRESSIVE"}))
    H264SceneChangeDetect.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    H264SceneChangeDetect.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    H264Settings.add_member(:adaptive_quantization, Smithy::Schema::Shapes::ShapeRef.new(shape: H264AdaptiveQuantization, location_name: 'AdaptiveQuantization', traits: {"smithy.api#documentation" => "Enables or disables adaptive quantization, which is a technique MediaLive can apply to video on a frame-by-frame basis to produce more compression without losing quality. There are three types of adaptive quantization: flicker, spatial, and temporal. Set the field in one of these ways: Set to Auto. Recommended. For each type of AQ, MediaLive will determine if AQ is needed, and if so, the appropriate strength. Set a strength (a value other than Auto or Disable). This strength will apply to any of the AQ fields that you choose to enable. Set to Disabled to disable all types of adaptive quantization.", "smithy.api#jsonName" => "adaptiveQuantization"}))
    H264Settings.add_member(:afd_signaling, Smithy::Schema::Shapes::ShapeRef.new(shape: AfdSignaling, location_name: 'AfdSignaling', traits: {"smithy.api#documentation" => "Indicates that AFD values will be written into the output stream.  If afdSignaling is \"auto\", the system will try to preserve the input AFD value (in cases where multiple AFD values are valid). If set to \"fixed\", the AFD value will be the value configured in the fixedAfd parameter.", "smithy.api#jsonName" => "afdSignaling"}))
    H264Settings.add_member(:bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1000, location_name: 'Bitrate', traits: {"smithy.api#documentation" => "Average bitrate in bits/second. Required when the rate control mode is VBR or CBR. Not used for QVBR. In an MS Smooth output group, each output must have a unique value when its bitrate is rounded down to the nearest multiple of 1000.", "smithy.api#jsonName" => "bitrate"}))
    H264Settings.add_member(:buf_fill_pct, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max100, location_name: 'BufFillPct', traits: {"smithy.api#documentation" => "Percentage of the buffer that should initially be filled (HRD buffer model).", "smithy.api#jsonName" => "bufFillPct"}))
    H264Settings.add_member(:buf_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'BufSize', traits: {"smithy.api#documentation" => "Size of buffer (HRD buffer model) in bits.", "smithy.api#jsonName" => "bufSize"}))
    H264Settings.add_member(:color_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: H264ColorMetadata, location_name: 'ColorMetadata', traits: {"smithy.api#documentation" => "Includes colorspace metadata in the output.", "smithy.api#jsonName" => "colorMetadata"}))
    H264Settings.add_member(:color_space_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: H264ColorSpaceSettings, location_name: 'ColorSpaceSettings', traits: {"smithy.api#documentation" => "Color Space settings", "smithy.api#jsonName" => "colorSpaceSettings"}))
    H264Settings.add_member(:entropy_encoding, Smithy::Schema::Shapes::ShapeRef.new(shape: H264EntropyEncoding, location_name: 'EntropyEncoding', traits: {"smithy.api#documentation" => "Entropy encoding mode.  Use cabac (must be in Main or High profile) or cavlc.", "smithy.api#jsonName" => "entropyEncoding"}))
    H264Settings.add_member(:filter_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: H264FilterSettings, location_name: 'FilterSettings', traits: {"smithy.api#documentation" => "Optional. Both filters reduce bandwidth by removing imperceptible details. You can enable one of the filters. We\nrecommend that you try both filters and observe the results to decide which one to use.\n\nThe Temporal Filter reduces bandwidth by removing imperceptible details in the content. It combines perceptual\nfiltering and motion compensated temporal filtering (MCTF). It operates independently of the compression level.\n\nThe Bandwidth Reduction filter is a perceptual filter located within the encoding loop. It adapts to the current\ncompression level to filter imperceptible signals. This filter works only when the resolution is 1080p or lower.", "smithy.api#jsonName" => "filterSettings"}))
    H264Settings.add_member(:fixed_afd, Smithy::Schema::Shapes::ShapeRef.new(shape: FixedAfd, location_name: 'FixedAfd', traits: {"smithy.api#documentation" => "Four bit AFD value to write on all frames of video in the output stream. Only valid when afdSignaling is set to 'Fixed'.", "smithy.api#jsonName" => "fixedAfd"}))
    H264Settings.add_member(:flicker_aq, Smithy::Schema::Shapes::ShapeRef.new(shape: H264FlickerAq, location_name: 'FlickerAq', traits: {"smithy.api#documentation" => "Flicker AQ makes adjustments within each frame to reduce flicker or 'pop' on I-frames. The value to enter in this field depends on the value in the Adaptive quantization field: If you have set the Adaptive quantization field to Auto, MediaLive ignores any value in this field. MediaLive will determine if flicker AQ is appropriate and will apply the appropriate strength. If you have set the Adaptive quantization field to a strength, you can set this field to Enabled or Disabled. Enabled: MediaLive will apply flicker AQ using the specified strength. Disabled: MediaLive won't apply flicker AQ. If you have set the Adaptive quantization to Disabled, MediaLive ignores any value in this field and doesn't apply flicker AQ.", "smithy.api#jsonName" => "flickerAq"}))
    H264Settings.add_member(:force_field_pictures, Smithy::Schema::Shapes::ShapeRef.new(shape: H264ForceFieldPictures, location_name: 'ForceFieldPictures', traits: {"smithy.api#documentation" => "This setting applies only when scan type is \"interlaced.\" It controls whether coding is performed on a field basis or on a frame basis. (When the video is progressive, the coding is always performed on a frame basis.)\nenabled: Force MediaLive to code on a field basis, so that odd and even sets of fields are coded separately.\ndisabled: Code the two sets of fields separately (on a field basis) or together (on a frame basis using PAFF), depending on what is most appropriate for the content.", "smithy.api#jsonName" => "forceFieldPictures"}))
    H264Settings.add_member(:framerate_control, Smithy::Schema::Shapes::ShapeRef.new(shape: H264FramerateControl, location_name: 'FramerateControl', traits: {"smithy.api#documentation" => "This field indicates how the output video frame rate is specified.  If \"specified\" is selected then the output video frame rate is determined by framerateNumerator and framerateDenominator, else if \"initializeFromSource\" is selected then the output video frame rate will be set equal to the input video frame rate of the first input.", "smithy.api#jsonName" => "framerateControl"}))
    H264Settings.add_member(:framerate_denominator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'FramerateDenominator', traits: {"smithy.api#documentation" => "Framerate denominator.", "smithy.api#jsonName" => "framerateDenominator"}))
    H264Settings.add_member(:framerate_numerator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'FramerateNumerator', traits: {"smithy.api#documentation" => "Framerate numerator - framerate is a fraction, e.g. 24000 / 1001 = 23.976 fps.", "smithy.api#jsonName" => "framerateNumerator"}))
    H264Settings.add_member(:gop_b_reference, Smithy::Schema::Shapes::ShapeRef.new(shape: H264GopBReference, location_name: 'GopBReference', traits: {"smithy.api#documentation" => "Documentation update needed", "smithy.api#jsonName" => "gopBReference"}))
    H264Settings.add_member(:gop_closed_cadence, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'GopClosedCadence', traits: {"smithy.api#documentation" => "Frequency of closed GOPs. In streaming applications, it is recommended that this be set to 1 so a decoder joining mid-stream will receive an IDR frame as quickly as possible. Setting this value to 0 will break output segmenting.", "smithy.api#jsonName" => "gopClosedCadence"}))
    H264Settings.add_member(:gop_num_b_frames, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max7, location_name: 'GopNumBFrames', traits: {"smithy.api#documentation" => "Number of B-frames between reference frames.", "smithy.api#jsonName" => "gopNumBFrames"}))
    H264Settings.add_member(:gop_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'GopSize', traits: {"smithy.api#documentation" => "GOP size (keyframe interval) in units of either frames or seconds per gopSizeUnits.\nIf gopSizeUnits is frames, gopSize must be an integer and must be greater than or equal to 1.\nIf gopSizeUnits is seconds, gopSize must be greater than 0, but need not be an integer.", "smithy.api#jsonName" => "gopSize"}))
    H264Settings.add_member(:gop_size_units, Smithy::Schema::Shapes::ShapeRef.new(shape: H264GopSizeUnits, location_name: 'GopSizeUnits', traits: {"smithy.api#documentation" => "Indicates if the gopSize is specified in frames or seconds. If seconds the system will convert the gopSize into a frame count at run time.", "smithy.api#jsonName" => "gopSizeUnits"}))
    H264Settings.add_member(:level, Smithy::Schema::Shapes::ShapeRef.new(shape: H264Level, location_name: 'Level', traits: {"smithy.api#documentation" => "H.264 Level.", "smithy.api#jsonName" => "level"}))
    H264Settings.add_member(:look_ahead_rate_control, Smithy::Schema::Shapes::ShapeRef.new(shape: H264LookAheadRateControl, location_name: 'LookAheadRateControl', traits: {"smithy.api#documentation" => "Amount of lookahead. A value of low can decrease latency and memory usage, while high can produce better quality for certain content.", "smithy.api#jsonName" => "lookAheadRateControl"}))
    H264Settings.add_member(:max_bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1000, location_name: 'MaxBitrate', traits: {"smithy.api#documentation" => "For QVBR: See the tooltip for Quality level\n\nFor VBR: Set the maximum bitrate in order to accommodate expected spikes in the complexity of the video.", "smithy.api#jsonName" => "maxBitrate"}))
    H264Settings.add_member(:min_i_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max30, location_name: 'MinIInterval', traits: {"smithy.api#documentation" => "Only meaningful if sceneChangeDetect is set to enabled.  Defaults to 5 if multiplex rate control is used.  Enforces separation between repeated (cadence) I-frames and I-frames inserted by Scene Change Detection. If a scene change I-frame is within I-interval frames of a cadence I-frame, the GOP is shrunk and/or stretched to the scene change I-frame. GOP stretch requires enabling lookahead as well as setting I-interval. The normal cadence resumes for the next GOP. Note: Maximum GOP stretch = GOP size + Min-I-interval - 1", "smithy.api#jsonName" => "minIInterval"}))
    H264Settings.add_member(:num_ref_frames, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max6, location_name: 'NumRefFrames', traits: {"smithy.api#documentation" => "Number of reference frames to use. The encoder may use more than requested if using B-frames and/or interlaced encoding.", "smithy.api#jsonName" => "numRefFrames"}))
    H264Settings.add_member(:par_control, Smithy::Schema::Shapes::ShapeRef.new(shape: H264ParControl, location_name: 'ParControl', traits: {"smithy.api#documentation" => "This field indicates how the output pixel aspect ratio is specified.  If \"specified\" is selected then the output video pixel aspect ratio is determined by parNumerator and parDenominator, else if \"initializeFromSource\" is selected then the output pixsel aspect ratio will be set equal to the input video pixel aspect ratio of the first input.", "smithy.api#jsonName" => "parControl"}))
    H264Settings.add_member(:par_denominator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'ParDenominator', traits: {"smithy.api#documentation" => "Pixel Aspect Ratio denominator.", "smithy.api#jsonName" => "parDenominator"}))
    H264Settings.add_member(:par_numerator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'ParNumerator', traits: {"smithy.api#documentation" => "Pixel Aspect Ratio numerator.", "smithy.api#jsonName" => "parNumerator"}))
    H264Settings.add_member(:profile, Smithy::Schema::Shapes::ShapeRef.new(shape: H264Profile, location_name: 'Profile', traits: {"smithy.api#documentation" => "H.264 Profile.", "smithy.api#jsonName" => "profile"}))
    H264Settings.add_member(:quality_level, Smithy::Schema::Shapes::ShapeRef.new(shape: H264QualityLevel, location_name: 'QualityLevel', traits: {"smithy.api#documentation" => "Leave as STANDARD_QUALITY or choose a different value (which might result in additional costs to run the channel).\n- ENHANCED_QUALITY: Produces a slightly better video quality without an increase in the bitrate. Has an effect only when the Rate control mode is QVBR or CBR. If this channel is in a MediaLive multiplex, the value must be ENHANCED_QUALITY.\n- STANDARD_QUALITY: Valid for any Rate control mode.", "smithy.api#jsonName" => "qualityLevel"}))
    H264Settings.add_member(:qvbr_quality_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max10, location_name: 'QvbrQualityLevel', traits: {"smithy.api#documentation" => "Controls the target quality for the video encode. Applies only when the rate control mode is QVBR. You can set a target quality or you can let MediaLive determine the best quality. To set a target quality, enter values in the QVBR quality level field and the Max bitrate field. Enter values that suit your most important viewing devices. Recommended values are:\n- Primary screen: Quality level: 8 to 10. Max bitrate: 4M\n- PC or tablet: Quality level: 7. Max bitrate: 1.5M to 3M\n- Smartphone: Quality level: 6. Max bitrate: 1M to 1.5M\nTo let MediaLive decide, leave the QVBR quality level field empty, and in Max bitrate enter the maximum rate you want in the video. For more information, see the section called \"Video - rate control mode\" in the MediaLive user guide", "smithy.api#jsonName" => "qvbrQualityLevel"}))
    H264Settings.add_member(:rate_control_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: H264RateControlMode, location_name: 'RateControlMode', traits: {"smithy.api#documentation" => "Rate control mode.\n\nQVBR: Quality will match the specified quality level except when it is constrained by the\nmaximum bitrate.  Recommended if you or your viewers pay for bandwidth.\n\nVBR: Quality and bitrate vary, depending on the video complexity. Recommended instead of QVBR\nif you want to maintain a specific average bitrate over the duration of the channel.\n\nCBR: Quality varies, depending on the video complexity. Recommended only if you distribute\nyour assets to devices that cannot handle variable bitrates.\n\nMultiplex: This rate control mode is only supported (and is required) when the video is being\ndelivered to a MediaLive Multiplex in which case the rate control configuration is controlled\nby the properties within the Multiplex Program.", "smithy.api#jsonName" => "rateControlMode"}))
    H264Settings.add_member(:scan_type, Smithy::Schema::Shapes::ShapeRef.new(shape: H264ScanType, location_name: 'ScanType', traits: {"smithy.api#documentation" => "Sets the scan type of the output to progressive or top-field-first interlaced.", "smithy.api#jsonName" => "scanType"}))
    H264Settings.add_member(:scene_change_detect, Smithy::Schema::Shapes::ShapeRef.new(shape: H264SceneChangeDetect, location_name: 'SceneChangeDetect', traits: {"smithy.api#documentation" => "Scene change detection.\n\n- On: inserts I-frames when scene change is detected.\n- Off: does not force an I-frame when scene change is detected.", "smithy.api#jsonName" => "sceneChangeDetect"}))
    H264Settings.add_member(:slices, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max32, location_name: 'Slices', traits: {"smithy.api#documentation" => "Number of slices per picture. Must be less than or equal to the number of macroblock rows for progressive pictures, and less than or equal to half the number of macroblock rows for interlaced pictures.\nThis field is optional; when no value is specified the encoder will choose the number of slices based on encode resolution.", "smithy.api#jsonName" => "slices"}))
    H264Settings.add_member(:softness, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max128, location_name: 'Softness', traits: {"smithy.api#documentation" => "Softness. Selects quantizer matrix, larger values reduce high-frequency content in the encoded image.  If not set to zero, must be greater than 15.", "smithy.api#jsonName" => "softness"}))
    H264Settings.add_member(:spatial_aq, Smithy::Schema::Shapes::ShapeRef.new(shape: H264SpatialAq, location_name: 'SpatialAq', traits: {"smithy.api#documentation" => "Spatial AQ makes adjustments within each frame based on spatial variation of content complexity. The value to enter in this field depends on the value in the Adaptive quantization field: If you have set the Adaptive quantization field to Auto, MediaLive ignores any value in this field. MediaLive will determine if spatial AQ is appropriate and will apply the appropriate strength. If you have set the Adaptive quantization field to a strength, you can set this field to Enabled or Disabled. Enabled: MediaLive will apply spatial AQ using the specified strength. Disabled: MediaLive won't apply spatial AQ. If you have set the Adaptive quantization to Disabled, MediaLive ignores any value in this field and doesn't apply spatial AQ.", "smithy.api#jsonName" => "spatialAq"}))
    H264Settings.add_member(:subgop_length, Smithy::Schema::Shapes::ShapeRef.new(shape: H264SubGopLength, location_name: 'SubgopLength', traits: {"smithy.api#documentation" => "If set to fixed, use gopNumBFrames B-frames per sub-GOP. If set to dynamic, optimize the number of B-frames used for each sub-GOP to improve visual quality.", "smithy.api#jsonName" => "subgopLength"}))
    H264Settings.add_member(:syntax, Smithy::Schema::Shapes::ShapeRef.new(shape: H264Syntax, location_name: 'Syntax', traits: {"smithy.api#documentation" => "Produces a bitstream compliant with SMPTE RP-2027.", "smithy.api#jsonName" => "syntax"}))
    H264Settings.add_member(:temporal_aq, Smithy::Schema::Shapes::ShapeRef.new(shape: H264TemporalAq, location_name: 'TemporalAq', traits: {"smithy.api#documentation" => "Temporal makes adjustments within each frame based on temporal variation of content complexity. The value to enter in this field depends on the value in the Adaptive quantization field: If you have set the Adaptive quantization field to Auto, MediaLive ignores any value in this field. MediaLive will determine if temporal AQ is appropriate and will apply the appropriate strength. If you have set the Adaptive quantization field to a strength, you can set this field to Enabled or Disabled. Enabled: MediaLive will apply temporal AQ using the specified strength. Disabled: MediaLive won't apply temporal AQ. If you have set the Adaptive quantization to Disabled, MediaLive ignores any value in this field and doesn't apply temporal AQ.", "smithy.api#jsonName" => "temporalAq"}))
    H264Settings.add_member(:timecode_insertion, Smithy::Schema::Shapes::ShapeRef.new(shape: H264TimecodeInsertionBehavior, location_name: 'TimecodeInsertion', traits: {"smithy.api#documentation" => "Determines how timecodes should be inserted into the video elementary stream.\n- 'disabled': Do not include timecodes\n- 'picTimingSei': Pass through picture timing SEI messages from the source specified in Timecode Config", "smithy.api#jsonName" => "timecodeInsertion"}))
    H264Settings.add_member(:timecode_burnin_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: TimecodeBurninSettings, location_name: 'TimecodeBurninSettings', traits: {"smithy.api#documentation" => "Timecode burn-in settings", "smithy.api#jsonName" => "timecodeBurninSettings"}))
    H264Settings.add_member(:min_qp, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max51, location_name: 'MinQp', traits: {"smithy.api#documentation" => "Sets the minimum QP. If you aren't familiar with quantization adjustment, leave the field empty. MediaLive will\napply an appropriate value.", "smithy.api#jsonName" => "minQp"}))
    H264Settings.type = Types::H264Settings
    H264SpatialAq.add_member(:disabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DISABLED', traits: {"smithy.api#enumValue" => "DISABLED"}))
    H264SpatialAq.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ENABLED', traits: {"smithy.api#enumValue" => "ENABLED"}))
    H264SubGopLength.add_member(:dynamic, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'DYNAMIC', traits: {"smithy.api#enumValue" => "DYNAMIC"}))
    H264SubGopLength.add_member(:fixed, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'FIXED', traits: {"smithy.api#enumValue" => "FIXED"}))
