    H265Settings.add_member(:adaptive_quantization, Smithy::Schema::Shapes::ShapeRef.new(shape: H265AdaptiveQuantization, location_name: 'AdaptiveQuantization', traits: {"smithy.api#documentation" => "Adaptive quantization. Allows intra-frame quantizers to vary to improve visual quality.", "smithy.api#jsonName" => "adaptiveQuantization"}))
    H265Settings.add_member(:afd_signaling, Smithy::Schema::Shapes::ShapeRef.new(shape: AfdSignaling, location_name: 'AfdSignaling', traits: {"smithy.api#documentation" => "Indicates that AFD values will be written into the output stream.  If afdSignaling is \"auto\", the system will try to preserve the input AFD value (in cases where multiple AFD values are valid). If set to \"fixed\", the AFD value will be the value configured in the fixedAfd parameter.", "smithy.api#jsonName" => "afdSignaling"}))
    H265Settings.add_member(:alternative_transfer_function, Smithy::Schema::Shapes::ShapeRef.new(shape: H265AlternativeTransferFunction, location_name: 'AlternativeTransferFunction', traits: {"smithy.api#documentation" => "Whether or not EML should insert an Alternative Transfer Function SEI message to support backwards compatibility with non-HDR decoders and displays.", "smithy.api#jsonName" => "alternativeTransferFunction"}))
    H265Settings.add_member(:bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin100000max40000000, location_name: 'Bitrate', traits: {"smithy.api#documentation" => "Average bitrate in bits/second. Required when the rate control mode is VBR or CBR. Not used for QVBR. In an MS Smooth output group, each output must have a unique value when its bitrate is rounded down to the nearest multiple of 1000.", "smithy.api#jsonName" => "bitrate"}))
    H265Settings.add_member(:buf_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin100000max80000000, location_name: 'BufSize', traits: {"smithy.api#documentation" => "Size of buffer (HRD buffer model) in bits.", "smithy.api#jsonName" => "bufSize"}))
    H265Settings.add_member(:color_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: H265ColorMetadata, location_name: 'ColorMetadata', traits: {"smithy.api#documentation" => "Includes colorspace metadata in the output.", "smithy.api#jsonName" => "colorMetadata"}))
    H265Settings.add_member(:color_space_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: H265ColorSpaceSettings, location_name: 'ColorSpaceSettings', traits: {"smithy.api#documentation" => "Color Space settings", "smithy.api#jsonName" => "colorSpaceSettings"}))
    H265Settings.add_member(:filter_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: H265FilterSettings, location_name: 'FilterSettings', traits: {"smithy.api#documentation" => "Optional. Both filters reduce bandwidth by removing imperceptible details. You can enable one of the filters. We\nrecommend that you try both filters and observe the results to decide which one to use.\n\nThe Temporal Filter reduces bandwidth by removing imperceptible details in the content. It combines perceptual\nfiltering and motion compensated temporal filtering (MCTF). It operates independently of the compression level.\n\nThe Bandwidth Reduction filter is a perceptual filter located within the encoding loop. It adapts to the current\ncompression level to filter imperceptible signals. This filter works only when the resolution is 1080p or lower.", "smithy.api#jsonName" => "filterSettings"}))
    H265Settings.add_member(:fixed_afd, Smithy::Schema::Shapes::ShapeRef.new(shape: FixedAfd, location_name: 'FixedAfd', traits: {"smithy.api#documentation" => "Four bit AFD value to write on all frames of video in the output stream. Only valid when afdSignaling is set to 'Fixed'.", "smithy.api#jsonName" => "fixedAfd"}))
    H265Settings.add_member(:flicker_aq, Smithy::Schema::Shapes::ShapeRef.new(shape: H265FlickerAq, location_name: 'FlickerAq', traits: {"smithy.api#documentation" => "If set to enabled, adjust quantization within each frame to reduce flicker or 'pop' on I-frames.", "smithy.api#jsonName" => "flickerAq"}))
    H265Settings.add_member(:framerate_denominator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max3003, location_name: 'FramerateDenominator', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "Framerate denominator.", "smithy.api#jsonName" => "framerateDenominator", "smithy.api#required" => {}}))
    H265Settings.add_member(:framerate_numerator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'FramerateNumerator', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "Framerate numerator - framerate is a fraction, e.g. 24000 / 1001 = 23.976 fps.", "smithy.api#jsonName" => "framerateNumerator", "smithy.api#required" => {}}))
    H265Settings.add_member(:gop_closed_cadence, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'GopClosedCadence', traits: {"smithy.api#documentation" => "Frequency of closed GOPs. In streaming applications, it is recommended that this be set to 1 so a decoder joining mid-stream will receive an IDR frame as quickly as possible. Setting this value to 0 will break output segmenting.", "smithy.api#jsonName" => "gopClosedCadence"}))
    H265Settings.add_member(:gop_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'GopSize', traits: {"smithy.api#documentation" => "GOP size (keyframe interval) in units of either frames or seconds per gopSizeUnits.\nIf gopSizeUnits is frames, gopSize must be an integer and must be greater than or equal to 1.\nIf gopSizeUnits is seconds, gopSize must be greater than 0, but need not be an integer.", "smithy.api#jsonName" => "gopSize"}))
    H265Settings.add_member(:gop_size_units, Smithy::Schema::Shapes::ShapeRef.new(shape: H265GopSizeUnits, location_name: 'GopSizeUnits', traits: {"smithy.api#documentation" => "Indicates if the gopSize is specified in frames or seconds. If seconds the system will convert the gopSize into a frame count at run time.", "smithy.api#jsonName" => "gopSizeUnits"}))
    H265Settings.add_member(:level, Smithy::Schema::Shapes::ShapeRef.new(shape: H265Level, location_name: 'Level', traits: {"smithy.api#documentation" => "H.265 Level.", "smithy.api#jsonName" => "level"}))
    H265Settings.add_member(:look_ahead_rate_control, Smithy::Schema::Shapes::ShapeRef.new(shape: H265LookAheadRateControl, location_name: 'LookAheadRateControl', traits: {"smithy.api#documentation" => "Amount of lookahead. A value of low can decrease latency and memory usage, while high can produce better quality for certain content.", "smithy.api#jsonName" => "lookAheadRateControl"}))
    H265Settings.add_member(:max_bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin100000max40000000, location_name: 'MaxBitrate', traits: {"smithy.api#documentation" => "For QVBR: See the tooltip for Quality level", "smithy.api#jsonName" => "maxBitrate"}))
    H265Settings.add_member(:min_i_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max30, location_name: 'MinIInterval', traits: {"smithy.api#documentation" => "Only meaningful if sceneChangeDetect is set to enabled.  Defaults to 5 if multiplex rate control is used.  Enforces separation between repeated (cadence) I-frames and I-frames inserted by Scene Change Detection. If a scene change I-frame is within I-interval frames of a cadence I-frame, the GOP is shrunk and/or stretched to the scene change I-frame. GOP stretch requires enabling lookahead as well as setting I-interval. The normal cadence resumes for the next GOP. Note: Maximum GOP stretch = GOP size + Min-I-interval - 1", "smithy.api#jsonName" => "minIInterval"}))
    H265Settings.add_member(:par_denominator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'ParDenominator', traits: {"smithy.api#documentation" => "Pixel Aspect Ratio denominator.", "smithy.api#jsonName" => "parDenominator"}))
    H265Settings.add_member(:par_numerator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'ParNumerator', traits: {"smithy.api#documentation" => "Pixel Aspect Ratio numerator.", "smithy.api#jsonName" => "parNumerator"}))
    H265Settings.add_member(:profile, Smithy::Schema::Shapes::ShapeRef.new(shape: H265Profile, location_name: 'Profile', traits: {"smithy.api#documentation" => "H.265 Profile.", "smithy.api#jsonName" => "profile"}))
    H265Settings.add_member(:qvbr_quality_level, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max10, location_name: 'QvbrQualityLevel', traits: {"smithy.api#documentation" => "Controls the target quality for the video encode. Applies only when the rate control mode is QVBR. Set values for the QVBR quality level field and Max bitrate field that suit your most important viewing devices. Recommended values are:\n- Primary screen: Quality level: 8 to 10. Max bitrate: 4M\n- PC or tablet: Quality level: 7. Max bitrate: 1.5M to 3M\n- Smartphone: Quality level: 6. Max bitrate: 1M to 1.5M", "smithy.api#jsonName" => "qvbrQualityLevel"}))
    H265Settings.add_member(:rate_control_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: H265RateControlMode, location_name: 'RateControlMode', traits: {"smithy.api#documentation" => "Rate control mode.\n\nQVBR: Quality will match the specified quality level except when it is constrained by the\nmaximum bitrate.  Recommended if you or your viewers pay for bandwidth.\n\nCBR: Quality varies, depending on the video complexity. Recommended only if you distribute\nyour assets to devices that cannot handle variable bitrates.\n\nMultiplex: This rate control mode is only supported (and is required) when the video is being\ndelivered to a MediaLive Multiplex in which case the rate control configuration is controlled\nby the properties within the Multiplex Program.", "smithy.api#jsonName" => "rateControlMode"}))
    H265Settings.add_member(:scan_type, Smithy::Schema::Shapes::ShapeRef.new(shape: H265ScanType, location_name: 'ScanType', traits: {"smithy.api#documentation" => "Sets the scan type of the output to progressive or top-field-first interlaced.", "smithy.api#jsonName" => "scanType"}))
    H265Settings.add_member(:scene_change_detect, Smithy::Schema::Shapes::ShapeRef.new(shape: H265SceneChangeDetect, location_name: 'SceneChangeDetect', traits: {"smithy.api#documentation" => "Scene change detection.", "smithy.api#jsonName" => "sceneChangeDetect"}))
    H265Settings.add_member(:slices, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max16, location_name: 'Slices', traits: {"smithy.api#documentation" => "Number of slices per picture. Must be less than or equal to the number of macroblock rows for progressive pictures, and less than or equal to half the number of macroblock rows for interlaced pictures.\nThis field is optional; when no value is specified the encoder will choose the number of slices based on encode resolution.", "smithy.api#jsonName" => "slices"}))
    H265Settings.add_member(:tier, Smithy::Schema::Shapes::ShapeRef.new(shape: H265Tier, location_name: 'Tier', traits: {"smithy.api#documentation" => "H.265 Tier.", "smithy.api#jsonName" => "tier"}))
    H265Settings.add_member(:timecode_insertion, Smithy::Schema::Shapes::ShapeRef.new(shape: H265TimecodeInsertionBehavior, location_name: 'TimecodeInsertion', traits: {"smithy.api#documentation" => "Determines how timecodes should be inserted into the video elementary stream.\n- 'disabled': Do not include timecodes\n- 'picTimingSei': Pass through picture timing SEI messages from the source specified in Timecode Config", "smithy.api#jsonName" => "timecodeInsertion"}))
    H265Settings.add_member(:timecode_burnin_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: TimecodeBurninSettings, location_name: 'TimecodeBurninSettings', traits: {"smithy.api#documentation" => "Timecode burn-in settings", "smithy.api#jsonName" => "timecodeBurninSettings"}))
    H265Settings.add_member(:mv_over_picture_boundaries, Smithy::Schema::Shapes::ShapeRef.new(shape: H265MvOverPictureBoundaries, location_name: 'MvOverPictureBoundaries', traits: {"smithy.api#documentation" => "If you are setting up the picture as a tile, you must set this to \"disabled\". In all other configurations, you typically enter \"enabled\".", "smithy.api#jsonName" => "mvOverPictureBoundaries"}))
    H265Settings.add_member(:mv_temporal_predictor, Smithy::Schema::Shapes::ShapeRef.new(shape: H265MvTemporalPredictor, location_name: 'MvTemporalPredictor', traits: {"smithy.api#documentation" => "If you are setting up the picture as a tile, you must set this to \"disabled\". In other configurations, you typically enter \"enabled\".", "smithy.api#jsonName" => "mvTemporalPredictor"}))
    H265Settings.add_member(:tile_height, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin64max2160, location_name: 'TileHeight', traits: {"smithy.api#documentation" => "Set this field to set up the picture as a tile. You must also set tileWidth.\nThe tile height must result in 22 or fewer rows in the frame. The tile width\nmust result in 20 or fewer columns in the frame. And finally, the product of the\ncolumn count and row count must be 64 of less.\nIf the tile width and height are specified, MediaLive will override the video\ncodec slices field with a value that MediaLive calculates", "smithy.api#jsonName" => "tileHeight"}))
    H265Settings.add_member(:tile_padding, Smithy::Schema::Shapes::ShapeRef.new(shape: H265TilePadding, location_name: 'TilePadding', traits: {"smithy.api#documentation" => "Set to \"padded\" to force MediaLive to add padding to the frame, to obtain a frame that is a whole multiple of the tile size.\nIf you are setting up the picture as a tile, you must enter \"padded\".\nIn all other configurations, you typically enter \"none\".", "smithy.api#jsonName" => "tilePadding"}))
    H265Settings.add_member(:tile_width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin256max3840, location_name: 'TileWidth', traits: {"smithy.api#documentation" => "Set this field to set up the picture as a tile. See tileHeight for more information.", "smithy.api#jsonName" => "tileWidth"}))
    H265Settings.add_member(:treeblock_size, Smithy::Schema::Shapes::ShapeRef.new(shape: H265TreeblockSize, location_name: 'TreeblockSize', traits: {"smithy.api#documentation" => "Select the tree block size used for encoding. If you enter \"auto\", the encoder will pick the best size. If you are setting up the picture as a tile, you must set this to 32x32. In all other configurations, you typically enter \"auto\".", "smithy.api#jsonName" => "treeblockSize"}))
    H265Settings.add_member(:min_qp, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1max51, location_name: 'MinQp', traits: {"smithy.api#documentation" => "Sets the minimum QP. If you aren't familiar with quantization adjustment, leave the field empty. MediaLive will\napply an appropriate value.", "smithy.api#jsonName" => "minQp"}))
    H265Settings.add_member(:deblocking, Smithy::Schema::Shapes::ShapeRef.new(shape: H265Deblocking, location_name: 'Deblocking', traits: {"smithy.api#documentation" => "Enable or disable the deblocking filter for this codec. The filter reduces blocking artifacts at block boundaries,\nwhich improves overall video quality. If the filter is disabled, visible block edges might appear in the output,\nespecially at lower bitrates.", "smithy.api#jsonName" => "deblocking"}))
    H265Settings.type = Types::H265Settings
