    H265Tier.add_member(:main, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'MAIN', traits: {"smithy.api#enumValue" => "MAIN"}))
