    Hdr10Settings.add_member(:max_cll, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max32768, location_name: 'MaxCll', traits: {"smithy.api#documentation" => "Maximum Content Light Level\nAn integer metadata value defining the maximum light level, in nits,\nof any single pixel within an encoded HDR video stream or file.", "smithy.api#jsonName" => "maxCll"}))
    Hdr10Settings.add_member(:max_fall, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max32768, location_name: 'MaxFall', traits: {"smithy.api#documentation" => "Maximum Frame Average Light Level\nAn integer metadata value defining the maximum average light level, in nits,\nfor any single frame within an encoded HDR video stream or file.", "smithy.api#jsonName" => "maxFall"}))
    Hdr10Settings.type = Types::Hdr10Settings
