    HlsAkamaiSettings.add_member(:filecache_duration, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max600, location_name: 'FilecacheDuration', traits: {"smithy.api#documentation" => "Size in seconds of file cache for streaming outputs.", "smithy.api#jsonName" => "filecacheDuration"}))
    HlsAkamaiSettings.add_member(:http_transfer_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsAkamaiHttpTransferMode, location_name: 'HttpTransferMode', traits: {"smithy.api#documentation" => "Specify whether or not to use chunked transfer encoding to Akamai. User should contact Akamai to enable this feature.", "smithy.api#jsonName" => "httpTransferMode"}))
    HlsAkamaiSettings.add_member(:num_retries, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'NumRetries', traits: {"smithy.api#documentation" => "Number of retry attempts that will be made before the Live Event is put into an error state. Applies only if the CDN destination URI begins with \"s3\" or \"mediastore\". For other URIs, the value is always 3.", "smithy.api#jsonName" => "numRetries"}))
    HlsAkamaiSettings.add_member(:restart_delay, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max15, location_name: 'RestartDelay', traits: {"smithy.api#documentation" => "If a streaming output fails, number of seconds to wait until a restart is initiated. A value of 0 means never restart.", "smithy.api#jsonName" => "restartDelay"}))
    HlsAkamaiSettings.add_member(:salt, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Salt', traits: {"smithy.api#documentation" => "Salt for authenticated Akamai.", "smithy.api#jsonName" => "salt"}))
    HlsAkamaiSettings.add_member(:token, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Token', traits: {"smithy.api#documentation" => "Token parameter for authenticated akamai. If not specified, _gda_ is used.", "smithy.api#jsonName" => "token"}))
    HlsAkamaiSettings.type = Types::HlsAkamaiSettings
    HlsBasicPutSettings.add_member(:connection_retry_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'ConnectionRetryInterval', traits: {"smithy.api#documentation" => "Number of seconds to wait before retrying connection to the CDN if the connection is lost.", "smithy.api#jsonName" => "connectionRetryInterval"}))
    HlsBasicPutSettings.add_member(:filecache_duration, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max600, location_name: 'FilecacheDuration', traits: {"smithy.api#documentation" => "Size in seconds of file cache for streaming outputs.", "smithy.api#jsonName" => "filecacheDuration"}))
