    HlsBasicPutSettings.add_member(:restart_delay, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max15, location_name: 'RestartDelay', traits: {"smithy.api#documentation" => "If a streaming output fails, number of seconds to wait until a restart is initiated. A value of 0 means never restart.", "smithy.api#jsonName" => "restartDelay"}))
