    HlsEncryptionType.add_member(:aes128, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'AES128', traits: {"smithy.api#enumValue" => "AES128"}))
