    HlsGroupSettings.add_member(:ad_markers, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofhlsadmarkers, location_name: 'AdMarkers', traits: {"smithy.api#documentation" => "Choose one or more ad marker types to pass SCTE35 signals through to this group of Apple HLS outputs.", "smithy.api#jsonName" => "adMarkers"}))
    HlsGroupSettings.add_member(:base_url_content, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BaseUrlContent', traits: {"smithy.api#documentation" => "A partial URI prefix that will be prepended to each output in the media .m3u8 file. Can be used if base manifest is delivered from a different URL than the main .m3u8 file.", "smithy.api#jsonName" => "baseUrlContent"}))
    HlsGroupSettings.add_member(:base_url_content1, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BaseUrlContent1', traits: {"smithy.api#documentation" => "Optional. One value per output group.\n\nThis field is required only if you are completing Base URL content A, and the downstream system has notified you that the media files for pipeline 1 of all outputs are in a location different from the media files for pipeline 0.", "smithy.api#jsonName" => "baseUrlContent1"}))
    HlsGroupSettings.add_member(:base_url_manifest, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BaseUrlManifest', traits: {"smithy.api#documentation" => "A partial URI prefix that will be prepended to each output in the media .m3u8 file. Can be used if base manifest is delivered from a different URL than the main .m3u8 file.", "smithy.api#jsonName" => "baseUrlManifest"}))
    HlsGroupSettings.add_member(:base_url_manifest1, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'BaseUrlManifest1', traits: {"smithy.api#documentation" => "Optional. One value per output group.\n\nComplete this field only if you are completing Base URL manifest A, and the downstream system has notified you that the child manifest files for pipeline 1 of all outputs are in a location different from the child manifest files for pipeline 0.", "smithy.api#jsonName" => "baseUrlManifest1"}))
    HlsGroupSettings.add_member(:caption_language_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: Listofcaptionlanguagemapping, location_name: 'CaptionLanguageMappings', traits: {"smithy.api#documentation" => "Mapping of up to 4 caption channels to caption languages.  Is only meaningful if captionLanguageSetting is set to \"insert\".", "smithy.api#jsonName" => "captionLanguageMappings"}))
    HlsGroupSettings.add_member(:caption_language_setting, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsCaptionLanguageSetting, location_name: 'CaptionLanguageSetting', traits: {"smithy.api#documentation" => "Applies only to 608 Embedded output captions.\ninsert: Include CLOSED-CAPTIONS lines in the manifest. Specify at least one language in the CC1 Language Code field. One CLOSED-CAPTION line is added for each Language Code you specify. Make sure to specify the languages in the order in which they appear in the original source (if the source is embedded format) or the order of the caption selectors (if the source is other than embedded). Otherwise, languages in the manifest will not match up properly with the output captions.\nnone: Include CLOSED-CAPTIONS=NONE line in the manifest.\nomit: Omit any CLOSED-CAPTIONS line from the manifest.", "smithy.api#jsonName" => "captionLanguageSetting"}))
    HlsGroupSettings.add_member(:client_cache, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsClientCache, location_name: 'ClientCache', traits: {"smithy.api#documentation" => "When set to \"disabled\", sets the #EXT-X-ALLOW-CACHE:no tag in the manifest, which prevents clients from saving media segments for later replay.", "smithy.api#jsonName" => "clientCache"}))
    HlsGroupSettings.add_member(:codec_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsCodecSpecification, location_name: 'CodecSpecification', traits: {"smithy.api#documentation" => "Specification to use (RFC-6381 or the default RFC-4281) during m3u8 playlist generation.", "smithy.api#jsonName" => "codecSpecification"}))
    HlsGroupSettings.add_member(:constant_iv, Smithy::Schema::Shapes::ShapeRef.new(shape: Stringmin32max32, location_name: 'ConstantIv', traits: {"smithy.api#documentation" => "For use with encryptionType. This is a 128-bit, 16-byte hex value represented by a 32-character text string. If ivSource is set to \"explicit\" then this parameter is required and is used as the IV for encryption.", "smithy.api#jsonName" => "constantIv"}))
    HlsGroupSettings.add_member(:destination, Smithy::Schema::Shapes::ShapeRef.new(shape: OutputLocationRef, location_name: 'Destination', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "A directory or HTTP destination for the HLS segments, manifest files, and encryption keys (if enabled).", "smithy.api#jsonName" => "destination", "smithy.api#required" => {}}))
    HlsGroupSettings.add_member(:directory_structure, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsDirectoryStructure, location_name: 'DirectoryStructure', traits: {"smithy.api#documentation" => "Place segments in subdirectories.", "smithy.api#jsonName" => "directoryStructure"}))
    HlsGroupSettings.add_member(:discontinuity_tags, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsDiscontinuityTags, location_name: 'DiscontinuityTags', traits: {"smithy.api#documentation" => "Specifies whether to insert EXT-X-DISCONTINUITY tags in the HLS child manifests for this output group.\nTypically, choose Insert because these tags are required in the manifest (according to the HLS specification) and serve an important purpose.\nChoose Never Insert only if the downstream system is doing real-time failover (without using the MediaLive automatic failover feature) and only if that downstream system has advised you to exclude the tags.", "smithy.api#jsonName" => "discontinuityTags"}))
    HlsGroupSettings.add_member(:encryption_type, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsEncryptionType, location_name: 'EncryptionType', traits: {"smithy.api#documentation" => "Encrypts the segments with the given encryption scheme.  Exclude this parameter if no encryption is desired.", "smithy.api#jsonName" => "encryptionType"}))
    HlsGroupSettings.add_member(:hls_cdn_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsCdnSettings, location_name: 'HlsCdnSettings', traits: {"smithy.api#documentation" => "Parameters that control interactions with the CDN.", "smithy.api#jsonName" => "hlsCdnSettings"}))
    HlsGroupSettings.add_member(:hls_id3_segment_tagging, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsId3SegmentTaggingState, location_name: 'HlsId3SegmentTagging', traits: {"smithy.api#documentation" => "State of HLS ID3 Segment Tagging", "smithy.api#jsonName" => "hlsId3SegmentTagging"}))
    HlsGroupSettings.add_member(:i_frame_only_playlists, Smithy::Schema::Shapes::ShapeRef.new(shape: IFrameOnlyPlaylistType, location_name: 'IFrameOnlyPlaylists', traits: {"smithy.api#documentation" => "DISABLED: Do not create an I-frame-only manifest, but do create the master and media manifests (according to the Output Selection field).\n\nSTANDARD: Create an I-frame-only manifest for each output that contains video, as well as the other manifests (according to the Output Selection field). The I-frame manifest contains a #EXT-X-I-FRAMES-ONLY tag to indicate it is I-frame only, and one or more #EXT-X-BYTERANGE entries identifying the I-frame position. For example, #EXT-X-BYTERANGE:160364@1461888\"", "smithy.api#jsonName" => "iFrameOnlyPlaylists"}))
    HlsGroupSettings.add_member(:incomplete_segment_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsIncompleteSegmentBehavior, location_name: 'IncompleteSegmentBehavior', traits: {"smithy.api#documentation" => "Specifies whether to include the final (incomplete) segment in the media output when the pipeline stops producing output because of a channel stop, a channel pause or a loss of input to the pipeline.\nAuto means that MediaLive decides whether to include the final segment, depending on the channel class and the types of output groups.\nSuppress means to never include the incomplete segment. We recommend you choose Auto and let MediaLive control the behavior.", "smithy.api#jsonName" => "incompleteSegmentBehavior"}))
    HlsGroupSettings.add_member(:index_n_segments, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin3, location_name: 'IndexNSegments', traits: {"smithy.api#documentation" => "Applies only if Mode field is LIVE.\n\nSpecifies the maximum number of segments in the media manifest file. After this maximum, older segments are removed from the media manifest. This number must be smaller than the number in the Keep Segments field.", "smithy.api#jsonName" => "indexNSegments"}))
    HlsGroupSettings.add_member(:input_loss_action, Smithy::Schema::Shapes::ShapeRef.new(shape: InputLossActionForHlsOut, location_name: 'InputLossAction', traits: {"smithy.api#documentation" => "Parameter that control output group behavior on input loss.", "smithy.api#jsonName" => "inputLossAction"}))
    HlsGroupSettings.add_member(:iv_in_manifest, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsIvInManifest, location_name: 'IvInManifest', traits: {"smithy.api#documentation" => "For use with encryptionType. The IV (Initialization Vector) is a 128-bit number used in conjunction with the key for encrypting blocks. If set to \"include\", IV is listed in the manifest, otherwise the IV is not in the manifest.", "smithy.api#jsonName" => "ivInManifest"}))
    HlsGroupSettings.add_member(:iv_source, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsIvSource, location_name: 'IvSource', traits: {"smithy.api#documentation" => "For use with encryptionType. The IV (Initialization Vector) is a 128-bit number used in conjunction with the key for encrypting blocks. If this setting is \"followsSegmentNumber\", it will cause the IV to change every segment (to match the segment number). If this is set to \"explicit\", you must enter a constantIv value.", "smithy.api#jsonName" => "ivSource"}))
    HlsGroupSettings.add_member(:keep_segments, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'KeepSegments', traits: {"smithy.api#documentation" => "Applies only if Mode field is LIVE.\n\nSpecifies the number of media segments to retain in the destination directory. This number should be bigger than indexNSegments (Num segments). We recommend (value = (2 x indexNsegments) + 1).\n\nIf this \"keep segments\" number is too low, the following might happen: the player is still reading a media manifest file that lists this segment, but that segment has been removed from the destination directory (as directed by indexNSegments). This situation would result in a 404 HTTP error on the player.", "smithy.api#jsonName" => "keepSegments"}))
    HlsGroupSettings.add_member(:key_format, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KeyFormat', traits: {"smithy.api#documentation" => "The value specifies how the key is represented in the resource identified by the URI.  If parameter is absent, an implicit value of \"identity\" is used.  A reverse DNS string can also be given.", "smithy.api#jsonName" => "keyFormat"}))
    HlsGroupSettings.add_member(:key_format_versions, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KeyFormatVersions', traits: {"smithy.api#documentation" => "Either a single positive integer version value or a slash delimited list of version values (1/2/3).", "smithy.api#jsonName" => "keyFormatVersions"}))
    HlsGroupSettings.add_member(:key_provider_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: KeyProviderSettings, location_name: 'KeyProviderSettings', traits: {"smithy.api#documentation" => "The key provider settings.", "smithy.api#jsonName" => "keyProviderSettings"}))
    HlsGroupSettings.add_member(:manifest_compression, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsManifestCompression, location_name: 'ManifestCompression', traits: {"smithy.api#documentation" => "When set to gzip, compresses HLS playlist.", "smithy.api#jsonName" => "manifestCompression"}))
