    HlsGroupSettings.add_member(:min_segment_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'MinSegmentLength', traits: {"smithy.api#documentation" => "Minimum length of MPEG-2 Transport Stream segments in seconds. When set, minimum segment length is enforced by looking ahead and back within the specified range for a nearby avail and extending the segment size if needed.", "smithy.api#jsonName" => "minSegmentLength"}))
    HlsGroupSettings.add_member(:mode, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsMode, location_name: 'Mode', traits: {"smithy.api#documentation" => "If \"vod\", all segments are indexed and kept permanently in the destination and manifest. If \"live\", only the number segments specified in keepSegments and indexNSegments are kept; newer segments replace older segments, which may prevent players from rewinding all the way to the beginning of the event.\n\nVOD mode uses HLS EXT-X-PLAYLIST-TYPE of EVENT while the channel is running, converting it to a \"VOD\" type manifest on completion of the stream.", "smithy.api#jsonName" => "mode"}))
    HlsGroupSettings.add_member(:output_selection, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsOutputSelection, location_name: 'OutputSelection', traits: {"smithy.api#documentation" => "MANIFESTS_AND_SEGMENTS: Generates manifests (master manifest, if applicable, and media manifests) for this output group.\n\nVARIANT_MANIFESTS_AND_SEGMENTS: Generates media manifests for this output group, but not a master manifest.\n\nSEGMENTS_ONLY: Does not generate any manifests for this output group.", "smithy.api#jsonName" => "outputSelection"}))
    HlsGroupSettings.add_member(:program_date_time, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsProgramDateTime, location_name: 'ProgramDateTime', traits: {"smithy.api#documentation" => "Includes or excludes EXT-X-PROGRAM-DATE-TIME tag in .m3u8 manifest files. The value is calculated using the program date time clock.", "smithy.api#jsonName" => "programDateTime"}))
    HlsGroupSettings.add_member(:program_date_time_clock, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsProgramDateTimeClock, location_name: 'ProgramDateTimeClock', traits: {"smithy.api#documentation" => "Specifies the algorithm used to drive the HLS EXT-X-PROGRAM-DATE-TIME clock. Options include:\n\nINITIALIZE_FROM_OUTPUT_TIMECODE: The PDT clock is initialized as a function of the first output timecode, then incremented by the EXTINF duration of each encoded segment.\n\nSYSTEM_CLOCK: The PDT clock is initialized as a function of the UTC wall clock, then incremented by the EXTINF duration of each encoded segment. If the PDT clock diverges from the wall clock by more than 500ms, it is resynchronized to the wall clock.", "smithy.api#jsonName" => "programDateTimeClock"}))
    HlsGroupSettings.add_member(:program_date_time_period, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max3600, location_name: 'ProgramDateTimePeriod', traits: {"smithy.api#documentation" => "Period of insertion of EXT-X-PROGRAM-DATE-TIME entry, in seconds.", "smithy.api#jsonName" => "programDateTimePeriod"}))
    HlsGroupSettings.add_member(:redundant_manifest, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsRedundantManifest, location_name: 'RedundantManifest', traits: {"smithy.api#documentation" => "ENABLED: The master manifest (.m3u8 file) for each pipeline includes information about both pipelines: first its own media files, then the media files of the other pipeline. This feature allows playout device that support stale manifest detection to switch from one manifest to the other, when the current manifest seems to be stale. There are still two destinations and two master manifests, but both master manifests reference the media files from both pipelines.\n\nDISABLED: The master manifest (.m3u8 file) for each pipeline includes information about its own pipeline only.\n\nFor an HLS output group with MediaPackage as the destination, the DISABLED behavior is always followed. MediaPackage regenerates the manifests it serves to players so a redundant manifest from MediaLive is irrelevant.", "smithy.api#jsonName" => "redundantManifest"}))
    HlsGroupSettings.add_member(:segment_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'SegmentLength', traits: {"smithy.api#documentation" => "Length of MPEG-2 Transport Stream segments to create in seconds. Note that segments will end on the next keyframe after this duration, so actual segment length may be longer.", "smithy.api#jsonName" => "segmentLength"}))
    HlsGroupSettings.add_member(:segmentation_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsSegmentationMode, location_name: 'SegmentationMode', traits: {"smithy.api#documentation" => "useInputSegmentation has been deprecated. The configured segment size is always used.", "smithy.api#jsonName" => "segmentationMode"}))
    HlsGroupSettings.add_member(:segments_per_subdirectory, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'SegmentsPerSubdirectory', traits: {"smithy.api#documentation" => "Number of segments to write to a subdirectory before starting a new one. directoryStructure must be subdirectoryPerStream for this setting to have an effect.", "smithy.api#jsonName" => "segmentsPerSubdirectory"}))
    HlsGroupSettings.add_member(:stream_inf_resolution, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsStreamInfResolution, location_name: 'StreamInfResolution', traits: {"smithy.api#documentation" => "Include or exclude RESOLUTION attribute for video in EXT-X-STREAM-INF tag of variant manifest.", "smithy.api#jsonName" => "streamInfResolution"}))
    HlsGroupSettings.add_member(:timed_metadata_id3_frame, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsTimedMetadataId3Frame, location_name: 'TimedMetadataId3Frame', traits: {"smithy.api#documentation" => "Indicates ID3 frame that has the timecode.", "smithy.api#jsonName" => "timedMetadataId3Frame"}))
    HlsGroupSettings.add_member(:timed_metadata_id3_period, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'TimedMetadataId3Period', traits: {"smithy.api#documentation" => "Timed Metadata interval in seconds.", "smithy.api#jsonName" => "timedMetadataId3Period"}))
    HlsGroupSettings.add_member(:timestamp_delta_milliseconds, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'TimestampDeltaMilliseconds', traits: {"smithy.api#documentation" => "Provides an extra millisecond delta offset to fine tune the timestamps.", "smithy.api#jsonName" => "timestampDeltaMilliseconds"}))
    HlsGroupSettings.add_member(:ts_file_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: HlsTsFileMode, location_name: 'TsFileMode', traits: {"smithy.api#documentation" => "SEGMENTED_FILES: Emit the program as segments - multiple .ts media files.\n\nSINGLE_FILE: Applies only if Mode field is VOD. Emit the program as a single .ts media file. The media manifest includes #EXT-X-BYTERANGE tags to index segments for playback. A typical use for this value is when sending the output to AWS Elemental MediaConvert, which can accept only a single media file. Playback while the channel is running is not guaranteed due to HTTP server caching.", "smithy.api#jsonName" => "tsFileMode"}))
