    M2tsSettings.add_member(:bitrate, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'Bitrate', traits: {"smithy.api#documentation" => "The output bitrate of the transport stream in bits per second. Setting to 0 lets the muxer automatically determine the appropriate bitrate.", "smithy.api#jsonName" => "bitrate"}))
    M2tsSettings.add_member(:buffer_model, Smithy::Schema::Shapes::ShapeRef.new(shape: M2tsBufferModel, location_name: 'BufferModel', traits: {"smithy.api#documentation" => "Controls the timing accuracy for output network traffic. Leave as MULTIPLEX to ensure accurate network packet timing. Or set to NONE, which might result in lower latency but will result in more variability in output network packet timing. This variability might cause interruptions, jitter, or bursty behavior in your playback or receiving devices.", "smithy.api#jsonName" => "bufferModel"}))
