    Mpeg2Settings.add_member(:adaptive_quantization, Smithy::Schema::Shapes::ShapeRef.new(shape: Mpeg2AdaptiveQuantization, location_name: 'AdaptiveQuantization', traits: {"smithy.api#documentation" => "Choose Off to disable adaptive quantization. Or choose another value to enable the quantizer and set its strength. The strengths are: Auto, Off, Low, Medium, High. When you enable this field, MediaLive allows intra-frame quantizers to vary, which might improve visual quality.", "smithy.api#jsonName" => "adaptiveQuantization"}))
    Mpeg2Settings.add_member(:afd_signaling, Smithy::Schema::Shapes::ShapeRef.new(shape: AfdSignaling, location_name: 'AfdSignaling', traits: {"smithy.api#documentation" => "Indicates the AFD values that MediaLive will write into the video encode. If you do not know what AFD signaling is, or if your downstream system has not given you guidance, choose AUTO.\nAUTO: MediaLive will try to preserve the input AFD value (in cases where multiple AFD values are valid).\nFIXED: MediaLive will use the value you specify in fixedAFD.", "smithy.api#jsonName" => "afdSignaling"}))
    Mpeg2Settings.add_member(:color_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: Mpeg2ColorMetadata, location_name: 'ColorMetadata', traits: {"smithy.api#documentation" => "Specifies whether to include the color space metadata. The metadata describes the color space that applies to the video (the colorSpace field). We recommend that you insert the metadata.", "smithy.api#jsonName" => "colorMetadata"}))
    Mpeg2Settings.add_member(:color_space, Smithy::Schema::Shapes::ShapeRef.new(shape: Mpeg2ColorSpace, location_name: 'ColorSpace', traits: {"smithy.api#documentation" => "Choose the type of color space conversion to apply to the output. For detailed information on setting up both the input and the output to obtain the desired color space in the output, see the section on \\\"MediaLive Features - Video - color space\\\" in the MediaLive User Guide.\nPASSTHROUGH: Keep the color space of the input content - do not convert it.\nAUTO:Convert all content that is SD to rec 601, and convert all content that is HD to rec 709.", "smithy.api#jsonName" => "colorSpace"}))
    Mpeg2Settings.add_member(:display_aspect_ratio, Smithy::Schema::Shapes::ShapeRef.new(shape: Mpeg2DisplayRatio, location_name: 'DisplayAspectRatio', traits: {"smithy.api#documentation" => "Sets the pixel aspect ratio for the encode.", "smithy.api#jsonName" => "displayAspectRatio"}))
    Mpeg2Settings.add_member(:filter_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: Mpeg2FilterSettings, location_name: 'FilterSettings', traits: {"smithy.api#documentation" => "Optionally specify a noise reduction filter, which can improve quality of compressed content. If you do not choose a filter, no filter will be applied.\nTEMPORAL: This filter is useful for both source content that is noisy (when it has excessive digital artifacts) and source content that is clean.\nWhen the content is noisy, the filter cleans up the source content before the encoding phase, with these two effects: First, it improves the output video quality because the content has been cleaned up. Secondly, it decreases the bandwidth because MediaLive does not waste bits on encoding noise.\nWhen the content is reasonably clean, the filter tends to decrease the bitrate.", "smithy.api#jsonName" => "filterSettings"}))
    Mpeg2Settings.add_member(:fixed_afd, Smithy::Schema::Shapes::ShapeRef.new(shape: FixedAfd, location_name: 'FixedAfd', traits: {"smithy.api#documentation" => "Complete this field only when afdSignaling is set to FIXED. Enter the AFD value (4 bits) to write on all frames of the video encode.", "smithy.api#jsonName" => "fixedAfd"}))
    Mpeg2Settings.add_member(:framerate_denominator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'FramerateDenominator', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "description\": \"The framerate denominator. For example, 1001. The framerate is the numerator divided by the denominator. For example, 24000 / 1001 = 23.976 FPS.", "smithy.api#jsonName" => "framerateDenominator", "smithy.api#required" => {}}))
    Mpeg2Settings.add_member(:framerate_numerator, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'FramerateNumerator', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "The framerate numerator. For example, 24000. The framerate is the numerator divided by the denominator. For example, 24000 / 1001 = 23.976 FPS.", "smithy.api#jsonName" => "framerateNumerator", "smithy.api#required" => {}}))
    Mpeg2Settings.add_member(:gop_closed_cadence, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'GopClosedCadence', traits: {"smithy.api#documentation" => "MPEG2: default is open GOP.", "smithy.api#jsonName" => "gopClosedCadence"}))
    Mpeg2Settings.add_member(:gop_num_b_frames, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max7, location_name: 'GopNumBFrames', traits: {"smithy.api#documentation" => "Relates to the GOP structure. The number of B-frames between reference frames. If you do not know what a B-frame is, use the default.", "smithy.api#jsonName" => "gopNumBFrames"}))
    Mpeg2Settings.add_member(:gop_size, Smithy::Schema::Shapes::ShapeRef.new(shape: Double, location_name: 'GopSize', traits: {"smithy.api#documentation" => "Relates to the GOP structure. The GOP size (keyframe interval) in the units specified in gopSizeUnits. If you do not know what GOP is, use the default.\nIf gopSizeUnits is frames, then the gopSize must be an integer and must be greater than or equal to 1.\nIf gopSizeUnits is seconds, the gopSize must be greater than 0, but does not need to be an integer.", "smithy.api#jsonName" => "gopSize"}))
    Mpeg2Settings.add_member(:gop_size_units, Smithy::Schema::Shapes::ShapeRef.new(shape: Mpeg2GopSizeUnits, location_name: 'GopSizeUnits', traits: {"smithy.api#documentation" => "Relates to the GOP structure. Specifies whether the gopSize is specified in frames or seconds. If you do not plan to change the default gopSize, leave the default. If you specify SECONDS, MediaLive will internally convert the gop size to a frame count.", "smithy.api#jsonName" => "gopSizeUnits"}))
    Mpeg2Settings.add_member(:scan_type, Smithy::Schema::Shapes::ShapeRef.new(shape: Mpeg2ScanType, location_name: 'ScanType', traits: {"smithy.api#documentation" => "Set the scan type of the output to PROGRESSIVE or INTERLACED (top field first).", "smithy.api#jsonName" => "scanType"}))
    Mpeg2Settings.add_member(:subgop_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Mpeg2SubGopLength, location_name: 'SubgopLength', traits: {"smithy.api#documentation" => "Relates to the GOP structure. If you do not know what GOP is, use the default.\nFIXED: Set the number of B-frames in each sub-GOP to the value in gopNumBFrames.\nDYNAMIC: Let MediaLive optimize the number of B-frames in each sub-GOP, to improve visual quality.", "smithy.api#jsonName" => "subgopLength"}))
    Mpeg2Settings.add_member(:timecode_insertion, Smithy::Schema::Shapes::ShapeRef.new(shape: Mpeg2TimecodeInsertionBehavior, location_name: 'TimecodeInsertion', traits: {"smithy.api#documentation" => "Determines how MediaLive inserts timecodes in the output video. For detailed information about setting up the input and the output for a timecode, see the section on \\\"MediaLive Features - Timecode configuration\\\" in the MediaLive User Guide.\nDISABLED: do not include timecodes.\nGOP_TIMECODE: Include timecode metadata in the GOP header.", "smithy.api#jsonName" => "timecodeInsertion"}))
    Mpeg2Settings.add_member(:timecode_burnin_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: TimecodeBurninSettings, location_name: 'TimecodeBurninSettings', traits: {"smithy.api#documentation" => "Timecode burn-in settings", "smithy.api#jsonName" => "timecodeBurninSettings"}))
    Mpeg2Settings.type = Types::Mpeg2Settings
