    MsSmoothGroupSettings.add_member(:audio_only_timecode_control, Smithy::Schema::Shapes::ShapeRef.new(shape: SmoothGroupAudioOnlyTimecodeControl, location_name: 'AudioOnlyTimecodeControl', traits: {"smithy.api#documentation" => "If set to passthrough for an audio-only MS Smooth output, the fragment absolute time will be set to the current timecode. This option does not write timecodes to the audio elementary stream.", "smithy.api#jsonName" => "audioOnlyTimecodeControl"}))
    MsSmoothGroupSettings.add_member(:certificate_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: SmoothGroupCertificateMode, location_name: 'CertificateMode', traits: {"smithy.api#documentation" => "If set to verifyAuthenticity, verify the https certificate chain to a trusted Certificate Authority (CA).  This will cause https outputs to self-signed certificates to fail.", "smithy.api#jsonName" => "certificateMode"}))
    MsSmoothGroupSettings.add_member(:connection_retry_interval, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'ConnectionRetryInterval', traits: {"smithy.api#documentation" => "Number of seconds to wait before retrying connection to the IIS server if the connection is lost. Content will be cached during this time and the cache will be be delivered to the IIS server once the connection is re-established.", "smithy.api#jsonName" => "connectionRetryInterval"}))
    MsSmoothGroupSettings.add_member(:destination, Smithy::Schema::Shapes::ShapeRef.new(shape: OutputLocationRef, location_name: 'Destination', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "Smooth Streaming publish point on an IIS server. Elemental Live acts as a \"Push\" encoder to IIS.", "smithy.api#jsonName" => "destination", "smithy.api#required" => {}}))
    MsSmoothGroupSettings.add_member(:event_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EventId', traits: {"smithy.api#documentation" => "MS Smooth event ID to be sent to the IIS server.\n\nShould only be specified if eventIdMode is set to useConfigured.", "smithy.api#jsonName" => "eventId"}))
    MsSmoothGroupSettings.add_member(:event_id_mode, Smithy::Schema::Shapes::ShapeRef.new(shape: SmoothGroupEventIdMode, location_name: 'EventIdMode', traits: {"smithy.api#documentation" => "Specifies whether or not to send an event ID to the IIS server. If no event ID is sent and the same Live Event is used without changing the publishing point, clients might see cached video from the previous run.\n\nOptions:\n- \"useConfigured\" - use the value provided in eventId\n- \"useTimestamp\" - generate and send an event ID based on the current timestamp\n- \"noEventId\" - do not send an event ID to the IIS server.", "smithy.api#jsonName" => "eventIdMode"}))
    MsSmoothGroupSettings.add_member(:event_stop_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: SmoothGroupEventStopBehavior, location_name: 'EventStopBehavior', traits: {"smithy.api#documentation" => "When set to sendEos, send EOS signal to IIS server when stopping the event", "smithy.api#jsonName" => "eventStopBehavior"}))
    MsSmoothGroupSettings.add_member(:filecache_duration, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'FilecacheDuration', traits: {"smithy.api#documentation" => "Size in seconds of file cache for streaming outputs.", "smithy.api#jsonName" => "filecacheDuration"}))
    MsSmoothGroupSettings.add_member(:fragment_length, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin1, location_name: 'FragmentLength', traits: {"smithy.api#documentation" => "Length of mp4 fragments to generate (in seconds). Fragment length must be compatible with GOP size and framerate.", "smithy.api#jsonName" => "fragmentLength"}))
    MsSmoothGroupSettings.add_member(:input_loss_action, Smithy::Schema::Shapes::ShapeRef.new(shape: InputLossActionForMsSmoothOut, location_name: 'InputLossAction', traits: {"smithy.api#documentation" => "Parameter that control output group behavior on input loss.", "smithy.api#jsonName" => "inputLossAction"}))
