    MsSmoothGroupSettings.add_member(:restart_delay, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0, location_name: 'RestartDelay', traits: {"smithy.api#documentation" => "Number of seconds before initiating a restart due to output failure, due to exhausting the numRetries on one segment, or exceeding filecacheDuration.", "smithy.api#jsonName" => "restartDelay"}))
