    VideoDescription.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Name', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "The name of this VideoDescription. Outputs will use this name to uniquely identify this Description.  Description names should be unique within this Live Event.", "smithy.api#jsonName" => "name", "smithy.api#required" => {}}))
    VideoDescription.add_member(:respond_to_afd, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoDescriptionRespondToAfd, location_name: 'RespondToAfd', traits: {"smithy.api#documentation" => "Indicates how MediaLive will respond to the AFD values that might be in the input video. If you do not know what AFD signaling is, or if your downstream system has not given you guidance, choose PASSTHROUGH.\nRESPOND: MediaLive clips the input video using a formula that uses the AFD values (configured in afdSignaling ), the input display aspect ratio, and the output display aspect ratio. MediaLive also includes the AFD values in the output, unless the codec for this encode is FRAME_CAPTURE.\nPASSTHROUGH: MediaLive ignores the AFD values and does not clip the video. But MediaLive does include the values in the output.\nNONE: MediaLive does not clip the input video and does not include the AFD values in the output", "smithy.api#jsonName" => "respondToAfd"}))
    VideoDescription.add_member(:scaling_behavior, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoDescriptionScalingBehavior, location_name: 'ScalingBehavior', traits: {"smithy.api#documentation" => "STRETCH_TO_OUTPUT configures the output position to stretch the video to the specified output resolution (height and width). This option will override any position value. DEFAULT may insert black boxes (pillar boxes or letter boxes) around the video to provide the specified output resolution.", "smithy.api#jsonName" => "scalingBehavior"}))
    VideoDescription.add_member(:sharpness, Smithy::Schema::Shapes::ShapeRef.new(shape: Integermin0max100, location_name: 'Sharpness', traits: {"smithy.api#documentation" => "Changes the strength of the anti-alias filter used for scaling. 0 is the softest setting, 100 is the sharpest. A setting of 50 is recommended for most content.", "smithy.api#jsonName" => "sharpness"}))
    VideoDescription.add_member(:width, Smithy::Schema::Shapes::ShapeRef.new(shape: Integer, location_name: 'Width', traits: {"smithy.api#documentation" => "Output video width, in pixels. Must be an even number. For most codecs, you can leave this field and height blank in order to use the height and width (resolution) from the source. Note, however, that leaving blank is not recommended. For the Frame Capture codec, height and width are required.", "smithy.api#jsonName" => "width"}))
