    VideoSelector.add_member(:color_space_settings, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoSelectorColorSpaceSettings, location_name: 'ColorSpaceSettings', traits: {"smithy.api#documentation" => "Color space settings", "smithy.api#jsonName" => "colorSpaceSettings"}))
    VideoSelector.add_member(:color_space_usage, Smithy::Schema::Shapes::ShapeRef.new(shape: VideoSelectorColorSpaceUsage, location_name: 'ColorSpaceUsage', traits: {"smithy.api#documentation" => "Applies only if colorSpace is a value other than follow. This field controls how the value in the colorSpace field will be used. fallback means that when the input does include color space data, that data will be used, but when the input has no color space data, the value in colorSpace will be used. Choose fallback if your input is sometimes missing color space data, but when it does have color space data, that data is correct. force means to always use the value in colorSpace. Choose force if your input usually has no color space data or might have unreliable color space data.", "smithy.api#jsonName" => "colorSpaceUsage"}))
